with with_gaps as (select *, case when lag(started_at) over (partition by country order by started_at asc, id asc) is null or started_at > lag(started_at) over (partition by country order by started_at asc, id asc) + interval '30' day then 1 else 0 end as is_new_burst from sessions) select id, customer_id, device, started_at, country, sum(is_new_burst) over (partition by country order by started_at asc, id asc rows between unbounded preceding and current row) as session_no from with_gaps;
